set -eu
test "$(git rev-parse HEAD)" = "4b06a39ebdb8a99d5544b27c8a52f33ad8e42440"
test -z "$(git status --porcelain --untracked-files=all)"
python3 -B - <<'PY'
import subprocess, json, re, selectors, time, os
c=subprocess.Popen(["docker","exec","-i","debug-ai-debug-ai-1","node","/app/bin/debugai-mcp.mjs"],stdin=subprocess.PIPE,stdout=subprocess.PIPE,stderr=subprocess.DEVNULL)
sel=selectors.DefaultSelector();sel.register(c.stdout,selectors.EVENT_READ)
buf=b""
def send(o):
 c.stdin.write((json.dumps(o)+"\n").encode());c.stdin.flush()
def call(i,m,p):
 global buf
 send(dict(jsonrpc="2.0",id=i,method=m,params=p))
 deadline=time.monotonic()+12
 while time.monotonic()<deadline:
  while b"\n" in buf:
   line,buf=buf.split(b"\n",1)
   try: v=json.loads(line)
   except ValueError: continue
   if v.get("id")==i:
    if "error" in v: raise RuntimeError("MCP_RPC_ERROR")
    return v["result"]
  if sel.select(max(0,deadline-time.monotonic())):
   chunk=os.read(c.stdout.fileno(),65536)
   if not chunk: raise RuntimeError("MCP_EOF")
   buf+=chunk
 raise RuntimeError("MCP_TIMEOUT")
def tool(i,name,args):
 o=call(i,"tools/call",{"name":name,"arguments":args})
 data=json.loads(o["content"][0]["text"])
 if o.get("isError") or data.get("exit_code")!=0:
  print("TOOL_FAILED="+name+" "+str(data.get("error",data.get("exit_code")))[:200]);raise SystemExit(4)
 return data["result"]
def find_run(o):
 if isinstance(o,dict):
  for k,v in o.items():
   if k=="run_id" and isinstance(v,str) and re.fullmatch(r"run_[a-zA-Z0-9_-]+",v):return v
   r=find_run(v)
   if r:return r
 if isinstance(o,list):
  for v in o:
   r=find_run(v)
   if r:return r
 return None
def states(o):
 out={}
 if isinstance(o,dict):
  for k in ("state","status","phase","stage","role","execution_mode","role_execution_mode"):
   v=o.get(k)
   if isinstance(v,str) and re.fullmatch(r"[a-zA-Z0-9_.-]{1,80}",v):out[k]=v
  for k in ("run","result","summary","workflow","progress","analysis"):
   if isinstance(o.get(k),dict):out.update({k+"."+a:b for a,b in states(o[k]).items()})
 return out
try:
 init=call(1,"initialize",{"protocolVersion":"2025-03-26","capabilities":{},"clientInfo":{"name":"debugai-live-qualification","version":"1"}})
 send({"jsonrpc":"2.0","method":"notifications/initialized"})
 names=[t["name"] for t in call(2,"tools/list",{})["tools"]]
 assert len(names)==13 and all(n in names for n in ("debugai_health","debugai_start","debugai_status","debugai_inspect"))
 print("MCP_TOOLS="+str(len(names)))
 tool(3,"debugai_health",{});print("MCP_HEALTH=PASS")
 # Probe observed missing run error, without reading any user payload.
 import urllib.request,urllib.error
 for endpoint in ("status","inspect"):
  try: urllib.request.urlopen("http://127.0.0.1:8787/v1/"+endpoint+"/run_mvrnydib_f5e96251e5",timeout=5)
  except urllib.error.HTTPError as e:
   o=json.loads(e.read())
   print("MISSING_RUN_"+endpoint.upper()+" HTTP="+str(e.code)+" "+json.dumps({k:o.get(k) for k in ("error","code")}))
 start=tool(4,"debugai_start",{"repo":"/workspace/debug-ai","request":"Investigate the observed HTTP 400 missing-run error classification: RunAuthority raises RUN_NOT_FOUND but the HTTP safeErrorCode reports generic ERROR. Inspect current code and tests, identify the actual cause and propose minimal regression-tested correction that preserves existing retention, authorization, and error redaction contracts. Analysis and candidate planning only; do not apply any patch. Use existing local model Gate roles."})
 rid=find_run(start)
 if not rid: print("START_KEYS="+str(list(start) if isinstance(start,dict) else type(start)));raise SystemExit(5)
 print("REAL_RUN_ID="+rid)
 print("MCP_START="+json.dumps(states(start)))
 for i,name in ((5,"debugai_status"),(6,"debugai_inspect")):
  print(name.upper()+"="+json.dumps(states(tool(i,name,{"run_id":rid}))))
finally:
 c.terminate()
 try:c.wait(timeout=3)
 except subprocess.TimeoutExpired:c.kill();c.wait()
PY
